#pragma once

#include <optional>
#include <string>
#include <vector>

#include "nlohmann/json.hpp"

namespace ocijail::rctl {

// Translate the OCI "linux.resources" object (as generated by CRI-O, podman
// and containerd from CRI/CLI resource settings) into FreeBSD rctl(8) rule
// fragments of the form "<resource>:<action>=<amount>". Pure function, no
// syscalls, so it can be unit tested.
//
//   memory.limit          -> memoryuse:sigkill: processes of the jail are
//                            killed when its resident memory exceeds the
//                            limit (closest match to Linux memory.max + OOM
//                            kill). Checked by racctd once per second, so a
//                            fast allocator can overshoot briefly.
//                            Deliberately NOT swapuse:deny: it charges
//                            writable anonymous mappings at mmap time, so Go
//                            (heap arena map), the JVM and other reserving
//                            allocators fail at startup with modest limits;
//                            and NOT memoryuse:deny: it only triggers
//                            reclaim and does nothing on hosts without swap.
//   cpu.quota/cpu.period  -> pcpu:deny=ceil(100*quota/period) (percent of one
//                            CPU, enforced by racct by suspending the jail's
//                            processes: coarse, ~1s granularity)
//   pids.limit            -> maxproc:deny
//
// cpu.shares has no FreeBSD equivalent (no proportional/group scheduling) and
// is reported in `ignored`.
struct translation {
    std::vector<std::string> rules;
    std::vector<std::string> ignored;
};
translation from_oci_resources(const nlohmann::json& resources);

// Add "jail:<jail_name>:<rule>" for each rule. Returns false if RACCT/RCTL
// is unavailable (kern.racct.enable=0 -> ENOSYS) or not permitted (EPERM,
// e.g. when ocijail itself runs inside a jail); throws on any other error.
bool apply(const std::string& jail_name, const std::vector<std::string>& rules);

// Remove every rule whose subject is jail:<jail_name>. rctl rules are keyed
// by jail *name* and outlive the jail, so this must run on delete. Missing
// RACCT, "no matching rule" and EPERM are not errors.
void remove(const std::string& jail_name);

}  // namespace ocijail::rctl
